<?php
declare(strict_types=1);
require_once dirname(__DIR__, 2) . '/src/bootstrap.php';
?><!doctype html>
<html lang="fr">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Galerie — MIARADI-TRAVEL</title>
<style>
:root{--red:#922D20;--paper:#FBF8F5;--ink:#211d1a;--muted:#706761;--line:rgba(33,29,26,.16);--soft:#F0EDE7;--serif:Georgia,serif;--sans:Arial,sans-serif}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.55 var(--sans)}button,input,select,textarea{font:inherit}button{cursor:pointer}.shell{max-width:1180px;margin:auto;padding:28px 20px 60px}.top{display:flex;justify-content:space-between;align-items:center;gap:16px;border-bottom:1px solid var(--line);padding-bottom:20px}.brand{color:var(--red);font-size:13px;letter-spacing:.16em;font-weight:700}.top h1{font:normal clamp(28px,5vw,48px)/1.1 var(--serif);margin:8px 0}.muted{color:var(--muted)}.button{border:0;padding:11px 15px;background:var(--red);color:white}.button.secondary{background:var(--soft);color:var(--ink);border:1px solid var(--line)}.panel{margin-top:24px;padding:clamp(18px,3vw,30px);background:white;border:1px solid var(--line)}.login{max-width:480px;margin:9vh auto}.field{display:grid;gap:6px;margin:12px 0}.field input,.field select,.field textarea{width:100%;padding:11px;border:1px solid var(--line);background:var(--paper);color:var(--ink)}.field textarea{min-height:80px}.row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.notice{min-height:24px;color:var(--red)}.hidden{display:none!important}.hint{font-size:12px;color:var(--muted)}.media-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.media-card{border:1px solid var(--line);padding:12px;min-width:0}.preview{width:100%;aspect-ratio:16/10;object-fit:cover;background:var(--soft);display:block}.media-card h3{font-size:16px;margin:10px 0 4px;overflow-wrap:anywhere}.pill{display:inline-block;background:var(--soft);padding:3px 7px;font-size:12px;margin:2px 4px 2px 0}.back{color:var(--red);text-decoration:none}.top-actions{display:flex;gap:8px;flex-wrap:wrap}@media(max-width:800px){.media-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.row,.media-grid{grid-template-columns:1fr}.top{align-items:flex-start;flex-direction:column}.shell{padding-inline:14px}}
 .quick-add{white-space:nowrap}@media(max-width:560px){.quick-add{width:100%}}\n</style>
</head>
<body><div class="shell">
<header class="top"><div><div class="brand">MIARADI — ADMINISTRATION</div><h1>Galerie multimédia</h1><div class="muted">Photos et vidéos de Madagascar</div></div><div class="top-actions"><a class="button secondary" href="index.php">Retour à l’administration</a><button class="button secondary hidden" id="logout">Déconnexion</button></div></header>
<section class="panel login" id="login-panel"><h2>Connexion administrateur</h2><p class="muted">Connectez-vous avec le compte MIARADI existant.</p><form id="login-form"><label class="field">Adresse e-mail<input type="email" name="email" autocomplete="username" required maxlength="254"></label><label class="field">Mot de passe<input type="password" name="password" autocomplete="current-password" required maxlength="1024"></label><button class="button" type="submit">Se connecter</button><p class="notice" id="login-status" role="status"></p></form></section>
<main id="dashboard" class="hidden"><p class="notice" id="notice" role="status"></p>
<section class="panel"><div class="actions" style="justify-content:space-between"><div><h2 id="form-title">Ajouter un média</h2><p class="muted">Images JPG, PNG, WebP (10 Mo max) ; vidéos MP4/WebM (100 Mo max) ou lien YouTube/Vimeo.</p></div><div class="actions"><button class="button secondary" id="add-photo" type="button">＋ Ajouter une photo</button><button class="button" id="add-video" type="button">＋ Ajouter une vidéo</button><button class="button secondary hidden" id="cancel-edit" type="button">Annuler la modification</button></div></div>
<form id="media-form" enctype="multipart/form-data">
<input type="hidden" name="id"><div class="row">
<label class="field">Type de média<select name="media_type" id="media-type"><option value="image">Photo</option><option value="video">Vidéo</option></select></label>
<label class="field">Source vidéo<select name="video-source" id="video-source"><option value="external">Lien YouTube / Vimeo</option><option value="upload">Fichier vidéo</option></select></label>
</div>
<label class="field">Circuit associé<select name="circuit_id" id="circuit-id"><option value="">Galerie générale — Madagascar</option></select><span class="hint">Choisissez un circuit pour afficher ce média sur sa fiche et dans la galerie générale. Laissez vide pour un média général.</span></label>\n<div class="row"><label class="field">Titre français<input name="title_fr" required maxlength="200"></label><label class="field">Titre anglais<input name="title_en" maxlength="200"></label></div>
<div class="row"><label class="field">Description française<textarea name="description_fr" maxlength="10000"></textarea></label><label class="field">Description anglaise<textarea name="description_en" maxlength="10000"></textarea></label></div>
<label class="field" id="alt-field">Texte alternatif (accessibilité)<input name="alt_text" maxlength="250"></label>
<label class="field hidden" id="url-field">Lien YouTube ou Vimeo<input name="external_url" type="url" placeholder="https://youtu.be/..."></label>
<label class="field" id="file-field">Fichier média<input name="media" id="media-file" type="file" accept="image/jpeg,image/png,image/webp" required><span class="hint" id="file-hint">JPG, PNG ou WebP — 10 Mo maximum.</span></label>
<div class="row"><label class="field">Ordre d’affichage<input name="sort_order" type="number" value="0" min="-100000" max="100000" required></label><label class="field"><span><input name="is_published" type="checkbox"> Publier sur le site</span><span class="hint">Les brouillons restent visibles uniquement dans l’administration.</span></label></div>
<div class="actions"><button class="button" type="submit" id="save-button">Enregistrer le média</button></div><p class="notice" id="form-status" role="status"></p>
</form></section>
<section class="panel"><div class="actions" style="justify-content:space-between"><h2>Bibliothèque</h2><label>Afficher <select id="filter"><option value="all">Tous les médias</option><option value="image">Photos</option><option value="video">Vidéos</option><option value="draft">Brouillons</option><option value="published">Publiés</option></select></label></div><div class="media-grid" id="media-list"></div></section>
</main></div>
<script>
(() => {
const $=s=>document.querySelector(s); let csrf=''; let items=[]; let circuits=[];
const api=path=>'../api/'+path;
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function notice(t){$('#notice').textContent=t||'';}
async function request(path,options={}){const headers={'Accept':'application/json',...(options.mutate?{'X-CSRF-Token':csrf}:{}),...(options.json?{'Content-Type':'application/json'}:{})};const r=await fetch(api(path),{credentials:'same-origin',...options,headers});const p=await r.json().catch(()=>({}));if(!r.ok)throw new Error(p.error?.message||'Une erreur est survenue.');return p;}
function show(session){csrf=session.csrfToken||'';$('#login-panel').classList.add('hidden');$('#dashboard').classList.remove('hidden');$('#logout').classList.remove('hidden');loadItems();}
async function session(){try{const r=await request('admin/session.php');if(r.data.authenticated)show(r.data);}catch(_){}}
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();$('#login-status').textContent='Connexion…';const f=new FormData(e.currentTarget);try{const r=await request('admin/session.php',{method:'POST',json:true,body:JSON.stringify({email:f.get('email'),password:f.get('password')})});$('#login-status').textContent='';show(r.data);}catch(err){$('#login-status').textContent=err.message;}});
$('#logout').addEventListener('click',async()=>{try{await request('admin/session.php',{method:'POST',json:true,mutate:true,body:JSON.stringify({action:'logout'})});}catch(_){}location.reload();});
function updateSourceFields(){const type=$('#media-type').value, source=$('#video-source').value;const editing=Boolean($('#media-form').elements.id.value);$('#video-source').closest('.field')?.classList.toggle('hidden',type!=='video');$('#url-field').classList.toggle('hidden',type!=='video'||source!=='external');$('#file-field').classList.toggle('hidden',type==='video'&&source==='external');$('#alt-field').classList.toggle('hidden',type!=='image');const file=$('#media-file');file.accept=type==='image'?'image/jpeg,image/png,image/webp':'video/mp4,video/webm';file.required=!editing&&!(type==='video'&&source==='external');$('#file-hint').textContent=type==='image'?'JPG, PNG ou WebP — 10 Mo maximum.':'MP4 ou WebM — 100 Mo maximum.';$('#url-field').querySelector('input').required=type==='video'&&source==='external';}
$('#media-type').addEventListener('change',updateSourceFields);$('#video-source').addEventListener('change',updateSourceFields);
function resetForm(){const f=$('#media-form');f.reset();f.elements.id.value='';$('#form-title').textContent='Ajouter un média';$('#save-button').textContent='Enregistrer le média';$('#cancel-edit').classList.add('hidden');$('#form-status').textContent='';updateSourceFields();}
$('#cancel-edit').addEventListener('click',resetForm);
function startNewMedia(type){resetForm();$('#media-type').value=type;$('#video-source').value='external';updateSourceFields();$('#media-form').scrollIntoView({behavior:'smooth',block:'start'});(type==='video'?$('#url-field input'):$('#media-file')).focus({preventScroll:true});}
$('#add-photo').addEventListener('click',()=>startNewMedia('image'));
$('#add-video').addEventListener('click',()=>startNewMedia('video'));
function render(){const filter=$('#filter').value;const visible=items.filter(i=>filter==='all'||(filter==='draft'?!i.is_published:filter==='published'?i.is_published:i.media_type===filter));$('#media-list').innerHTML=visible.map(i=>{const preview=i.thumbnail_path||i.file_path;const src=preview?(preview.startsWith('http')?preview:'../'+preview):'';return '<article class="media-card">'+(src?'<img class="preview" loading="lazy" src="'+esc(src)+'" alt="">':'<div class="preview" style="display:grid;place-items:center">Vidéo</div>')+'<div><span class="pill">'+(i.media_type==='image'?'Photo':'Vidéo')+'</span><span class="pill">'+(i.is_published?'Publié':'Brouillon')+'</span><span class="pill">'+esc(i.source_type)+'</span><span class="pill">'+esc(i.circuit_title_fr||'Galerie générale')+'</span></div><h3>'+esc(i.title_fr)+'</h3><p class="muted">'+esc(i.title_en||'')+'</p><div class="actions"><button class="button secondary" data-edit="'+i.id+'">Modifier</button><button class="button secondary" data-toggle="'+i.id+'">'+(i.is_published?'Masquer':'Publier')+'</button><button class="button secondary" data-delete="'+i.id+'">Supprimer</button></div></article>';}).join('')||'<p class="muted">Aucun média dans cette sélection.</p>';
$('#media-list').querySelectorAll('[data-edit]').forEach(b=>b.addEventListener('click',()=>edit(Number(b.dataset.edit))));$('#media-list').querySelectorAll('[data-toggle]').forEach(b=>b.addEventListener('click',()=>toggle(Number(b.dataset.toggle))));$('#media-list').querySelectorAll('[data-delete]').forEach(b=>b.addEventListener('click',()=>remove(Number(b.dataset.delete))));}
function renderCircuitOptions(){const select=$('#circuit-id');const current=select.value;select.innerHTML='<option value="">Galerie générale — Madagascar</option>'+circuits.map(c=>'<option value="'+c.id+'">'+esc(c.title_fr||c.slug)+(c.is_published?'':' (brouillon)')+'</option>').join('');select.value=current;}
async function loadItems(){try{const r=await request('admin/gallery.php');items=r.data;circuits=r.circuits||[];renderCircuitOptions();render();}catch(e){notice(e.message);}}
function edit(id){const item=items.find(i=>i.id===id);if(!item)return;const f=$('#media-form');f.reset();f.elements.id.value=item.id;f.elements.media_type.value=item.media_type;$('#video-source').value=item.source_type==='upload'?'upload':'external';for(const k of ['title_fr','title_en','description_fr','description_en','alt_text','sort_order'])f.elements[k].value=item[k]??(k==='sort_order'?0:'');f.elements.circuit_id.value=item.circuit_id??'';f.elements.external_url.value=item.external_url||'';f.elements.is_published.checked=item.is_published;$('#form-title').textContent='Modifier le média';$('#save-button').textContent='Enregistrer les modifications';$('#cancel-edit').classList.remove('hidden');$('#form-status').textContent='';updateSourceFields();$('#media-file').required=false;$('#media-form').scrollIntoView({behavior:'smooth',block:'start'});}
async function toggle(id){const i=items.find(x=>x.id===id);if(!i)return;const body={id,media_type:i.media_type,circuit_id:i.circuit_id,title_fr:i.title_fr,title_en:i.title_en,description_fr:i.description_fr,description_en:i.description_en,alt_text:i.alt_text,sort_order:i.sort_order,is_published:!i.is_published};if(i.media_type==='video')body.external_url=i.external_url;try{await request('admin/gallery.php',{method:'PATCH',json:true,mutate:true,body:JSON.stringify(body)});notice('Publication mise à jour.');await loadItems();}catch(e){notice(e.message);}}
async function remove(id){if(!confirm('Supprimer définitivement ce média ?'))return;try{await request('admin/gallery.php?id='+id,{method:'DELETE',mutate:true});notice('Média supprimé.');await loadItems();}catch(e){notice(e.message);}}
$('#filter').addEventListener('change',render);
$('#media-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget;const id=f.elements.id.value;const type=f.elements.media_type.value;const source=$('#video-source').value;const status=$('#form-status');status.textContent='Enregistrement…';try{let result;if(!id&&!(type==='video'&&source==='external')){const data=new FormData(f);data.delete('video-source');data.set('media_type',type);data.set('circuit_id',f.elements.circuit_id.value);data.set('is_published',f.elements.is_published.checked?'1':'0');result=await request('admin/gallery.php',{method:'POST',mutate:true,body:data});}else{const body={media_type:type,circuit_id:f.elements.circuit_id.value||null,title_fr:f.elements.title_fr.value.trim(),title_en:f.elements.title_en.value.trim()||null,description_fr:f.elements.description_fr.value.trim()||null,description_en:f.elements.description_en.value.trim()||null,alt_text:f.elements.alt_text.value.trim()||null,sort_order:Number(f.elements.sort_order.value||0),is_published:f.elements.is_published.checked};if(id)body.id=Number(id);if(type==='video'&&source==='external')body.external_url=f.elements.external_url.value.trim();else if(!id){status.textContent='Choisissez un fichier média ou un lien vidéo.';return;}result=await request('admin/gallery.php',{method:id?'PATCH':'POST',json:true,mutate:true,body:JSON.stringify(body)});}status.textContent='';notice('Média enregistré.');resetForm();await loadItems();}catch(err){status.textContent=err.message;}});
updateSourceFields();session();
})();
</script></body></html>
